module negabase_converter (input clk, input rst_n, input start, input [63:0] p, input [15:0] k, output reg [5:0] count, output reg [15:0] coeff_out, output reg done); reg [63:0] p_reg; reg [15:0] k_reg; reg [2:0] state_reg; reg [15:0] coeff_buf [0:63]; reg [6:0] coeff_index; reg [5:0] count_reg; reg done_reg; localparam IDLE = 3'd0; localparam PROCESSING = 3'd1; localparam OUTPUT = 3'd2; localparam DONE = 3'd3; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin p_reg <= 64'b0; k_reg <= 16'b0; state_reg <= IDLE; coeff_index <= 0; count_reg <=0; done_reg <=0; end else begin if (state_reg == IDLE) begin if (start) begin p_reg <= p; k_reg <= k; state_reg <= PROCESSING; coeff_index <=0; count_reg <=0; end end else if (state_reg == PROCESSING) begin reg signed [63:0] temp_p; reg [15:0] r; reg signed [63:0] new_p; temp_p = p_reg; r = temp_p % (signed)k_reg; if (r < 0) begin r = r + k_reg; temp_p = temp_p + k_reg; end new_p = - (temp_p / (signed)k_reg); coeff_buf[coeff_index] = r; coeff_index <= coeff_index + 1; count_reg <= coeff_index + 1; p_reg <= new_p; if (new_p == 0) state_reg <= OUTPUT; else state_reg <= PROCESSING; end else if (state_reg == OUTPUT) begin if (coeff_index > 0) begin coeff_out <= coeff_buf[coeff_index - 1]; coeff_index <= coeff_index - 1; done_reg <=0; end else begin done_reg <=1; end end else if (state_reg == DONE) begin done_reg <=1; end end end end done <= done_reg; count <= count_reg; endmodule